def main():
    c = sqlite3.connect(DB); c.row_factory = sqlite3.Row
    changed = missing = 0
    for qid, new in REWRITES.items():
        cur = c.execute("SELECT definition FROM questions WHERE id=?", (qid,)).fetchone()
        if cur is None:
            missing += 1; print("  MISSING:", qid); continue
        if (cur["definition"] or "") == new:
            continue
        changed += 1
        if WRITE:
            c.execute("UPDATE questions SET definition=? WHERE id=?", (new, qid))
    if WRITE:
        c.commit()
    print(("APPLIED" if WRITE else "DRY RUN") + " — %d/%d definitions updated (%d missing)" % (changed, len(REWRITES), missing))
    c.close()


if __name__ == "__main__":
    sys.exit(main() or 0)
